  CAST(ts_utc AS TIMESTAMP) AS ts_utc,
  CAST(rain_mm AS DOUBLE) AS rain_mm,
  CAST(discharge_m3s AS DOUBLE) AS discharge_m3s,
  CAST(NULL AS STRING) AS warning_level
